/* Unified reviews MVP. Browser persistence and role simulation, no backend authorization. */
const urToday='2026-10-19', urTypes=['Self','Manager','Peer','Upward'], urStatus=['Not Started','In Progress','Submitted','Completed','Overdue'];
const urUid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
const urClone=x=>structuredClone(x), urHr=()=>viewRole==='HR Administrator';
function urUser(){return viewRole==='Employee'?'EMP-003':viewRole==='Manager'?'MGR-001':'HR-001'}
function urPerson(id){const e=data.employees.find(e=>e[0]===id);return e?{id:e[0],name:e[1],position:e[2],department:e[3],manager:e[4]}:id==='MGR-001'?{id,name:'Angela Reyes',position:'Department Manager',department:'Operations',manager:'Maria Angeles'}:id==='HR-001'?{id,name:'Maria Angeles',position:'HR Administrator',department:'Human Resources',manager:''}:{id,name:'Unassigned',position:'',department:'',manager:''}}
function urPeople(){return [...data.employees.map(e=>urPerson(e[0])),urPerson('MGR-001'),urPerson('HR-001')]}
function urSupervisor(id){return urPeople().find(p=>p.name===urPerson(id).manager)?.id||''}
function urQuestion(title,type='Rating',section='Job Performance',required=true){return {id:urUid('q'),title,type,section,description:'',required,notObserved:type==='Rating',options:type==='Choice'?['On track','Needs support','Exceeded expectations']:[]}}
function urTemplate(name,type,category,questions,status='Published'){return {id:urUid('tpl'),name,description:'Reflect on observable behaviors and use specific examples.',type,category,status,version:1,updated:urToday,sections:[...new Set(questions.map(q=>q.section))],questions}}
function urSeed(){
 const common=()=>[urQuestion('Delivers work that meets agreed standards.'),urQuestion('Demonstrates accountability for assigned responsibilities.','Rating','Competencies'),urQuestion('Communicates clearly with team members.','Rating','Communication and Collaboration'),urQuestion('What are this employee’s greatest strengths?','Paragraph','Strengths and Areas for Improvement'),urQuestion('What areas could this employee improve?','Paragraph','Strengths and Areas for Improvement'),urQuestion('What recommendations would support professional growth?','Paragraph','Overall Evaluation',false)];
 const feedback=[...['Communicates clearly with team members.','Collaborates effectively with others.','Demonstrates accountability for assigned responsibilities.','Handles challenges and resolves problems effectively.','Demonstrates professionalism in the workplace.'].map(t=>urQuestion(t,'Rating','Competencies')),...['What are this employee’s greatest strengths?','What areas could this employee improve?','What recommendations would support this employee’s professional growth?'].map(t=>urQuestion(t,'Paragraph','Strengths and Areas for Improvement'))];
 const templates=[urTemplate('Annual Performance Review','Manager','General Performance',common()),urTemplate('Quarterly Performance Review','Manager','General Performance',common()),urTemplate('Self-Assessment','Self','Self-Assessment',[urQuestion('How consistently do you meet your goals?'),urQuestion('What are your greatest strengths?','Paragraph','Strengths and Areas for Improvement'),urQuestion('What areas could you improve?','Paragraph','Strengths and Areas for Improvement'),urQuestion('Describe one achievement in a sentence.','Short','Overall Evaluation'),urQuestion('What support do you need?','Choice','Overall Evaluation',false)]),urTemplate('Manager Evaluation','Manager','Manager Evaluation',common()),urTemplate('Peer Feedback','Peer','Peer Feedback',feedback),urTemplate('360° Feedback','Peer','360° Feedback',feedback),urTemplate('Probationary Evaluation','Manager','Probationary Evaluation',common(),'Draft')];
 const map={Self:templates[2].id,Manager:templates[3].id,Peer:templates[5].id,Upward:templates[5].id};
 const cycle=(id,name,type,status,start,deadline,ids)=>({id,name,type,status,description:'A structured conversation about performance and growth.',periodStart:'2026-07-01',periodEnd:'2026-09-30',start,deadline,participants:ids,groups:['Self','Manager'],evaluators:ids.flatMap(id=>[{subject:id,reviewer:id,type:'Self'},{subject:id,reviewer:urSupervisor(id)||'MGR-001',type:'Manager'}]),templates:{...map},anonymousPeer:true,anonymousUpward:true,threshold:3,released:false,finalComments:{},created:urToday});
 const cycles=[cycle('unified-q4','Q4 Performance Review 2026','Standard Performance Review','Active','2026-10-01','2026-10-30',data.employees.map(e=>e[0])),cycle('unified-midyear','Mid-Year Performance Review','Standard Performance Review','Completed','2026-07-01','2026-07-31',['EMP-001','EMP-003']),cycle('unified-360','Leadership 360° Feedback','360° Feedback','Active','2026-10-01','2026-10-25',['EMP-001']),cycle('unified-annual','Annual Performance Review 2026','Standard Performance Review','Draft','2027-01-04','2027-01-29',data.employees.map(e=>e[0])),cycle('unified-probation','Probationary Evaluation — October 2026','Probationary Review','Scheduled','2026-10-26','2026-11-06',['EMP-006'])];
 cycles[1].released=true;cycles[1].finalComments={'EMP-003':'Strong campaign execution. Focus next on measurement and sharing results with the wider team.','EMP-001':'Reliable design delivery. Continue strengthening early stakeholder alignment.'};cycles[2].groups=['Self','Manager','Peer','Upward'];cycles[2].evaluators.push(...['EMP-002','EMP-003','EMP-004'].map(reviewer=>({subject:'EMP-001',reviewer,type:'Peer'})),...['EMP-005','EMP-006','EMP-004'].map(reviewer=>({subject:'EMP-001',reviewer,type:'Upward'})));cycles[4].scheduledAt=urToday;
 const assignments=[];for(const c of cycles.filter(c=>['Active','Completed'].includes(c.status))){for(const e of c.evaluators){let t=templates.find(t=>t.id===map[e.type]);assignments.push({id:urUid('rev'),cycle:c.id,...e,deadline:c.deadline,template:urClone(t),state:'Not Started',answers:{},updated:urToday})}}
 function answer(a,n){a.state=n;a.answers=Object.fromEntries(a.template.questions.map(q=>[q.id,q.type==='Rating'?'4':q.type==='Choice'?q.options[0]:q.title.toLowerCase().includes('improv')?'Share progress earlier and strengthen prioritization.':q.title.toLowerCase().includes('strength')?'Reliable delivery, thoughtful collaboration, and clear communication.':'Delivered the agreed milestones and supported colleagues with specific, practical input.']));a.submitted=urToday}
 assignments.filter(a=>a.cycle==='unified-midyear').forEach(a=>answer(a,'Completed'));
 assignments.filter(a=>a.cycle==='unified-q4'&&['EMP-001','EMP-002'].includes(a.subject)&&a.type==='Self').forEach(a=>answer(a,'Submitted'));
 assignments.filter(a=>a.cycle==='unified-q4'&&a.subject==='EMP-003'&&a.type==='Self').forEach(a=>{answer(a,'In Progress');delete a.answers[a.template.questions.at(-2).id]});
 assignments.filter(a=>a.cycle==='unified-360'&&a.type==='Peer'&&a.reviewer!=='EMP-003').forEach(a=>answer(a,'Submitted'));
 assignments.filter(a=>a.cycle==='unified-360'&&a.type==='Upward').forEach(a=>answer(a,'Submitted'));
 const overdue=assignments.find(a=>a.cycle==='unified-q4'&&a.subject==='EMP-006'&&a.type==='Self');if(overdue)overdue.deadline='2026-10-16';
 return {version:1,templates,cycles,assignments,draftCycle:null,audit:[]};
}
if(!data.unifiedReviews)data.unifiedReviews=urSeed();
const UR=data.unifiedReviews;let urTab='Reviews',urScreen='list',urFilter={view:'All Reviews',q:'',cycle:'All cycles',type:'All types',department:'All departments',status:'All statuses'},urTemplateFilter='',urCycleFilter={q:'',status:'All statuses',type:'All types',period:'All periods'},urEditor=null,urWizard=null,urStep=1,urDetail=null,urDetailTab='Overview',urAnswers={},urDirty=false,urPreview=false,urPending=null;
function urPersist(){save()}
function urAudit(action){UR.audit.push({at:new Date().toISOString(),by:urUser(),action});urPersist()}
function urBadge(s){const c={ 'Not Started':'neutral','In Progress':'blue',Submitted:'purple',Completed:'green',Overdue:'red',Draft:'neutral',Scheduled:'purple',Active:'blue',Cancelled:'red',Published:'green',Archived:'neutral'};return `<span class="pill ${c[s]||'neutral'}">${esc(s)}</span>`}
function urCycle(id){return UR.cycles.find(c=>c.id===id)}
function urEffective(a){return ['Not Started','In Progress'].includes(a.state)&&a.deadline<urToday?'Overdue':a.state}
function urAnon(a){const c=urCycle(a.cycle);return a.type==='Peer'&&c.anonymousPeer||a.type==='Upward'&&c.anonymousUpward}
function urTeam(id){return data.employees.some(e=>e[0]===id&&e[4]===managerName)}
function urVisible(a){return urHr()||a.reviewer===urUser()||a.subject===urUser()||viewRole==='Manager'&&urTeam(a.subject)}
function urCanEdit(a){return a.reviewer===urUser()&&urCycle(a.cycle).status==='Active'&&['Not Started','In Progress'].includes(a.state)}
function urCanRead(a){return a.reviewer===urUser()||!urAnon(a)&&(urHr()||urCycle(a.cycle).released&&(a.subject===urUser()||viewRole==='Manager'&&urTeam(a.subject)))}
function urCanResult(c,subject){return c.released&&(urHr()||subject===urUser()||viewRole==='Manager'&&urTeam(subject))}
function urDisplayPerson(id){const p=urPerson(id);return `<div class="person"><span class="avatar">${initials(p.name)}</span><div>${esc(p.name)}<small>${esc(p.position)}</small></div></div>`}
function urMean(a){const nums=a.template.questions.filter(q=>q.type==='Rating').map(q=>a.answers[q.id]).filter(v=>v&&v!=='NO').map(Number);return nums.length?nums.reduce((s,n)=>s+n,0)/nums.length:null}
function urAvg(nums){const valid=nums.filter(x=>x!==null&&Number.isFinite(x));return valid.length?valid.reduce((s,n)=>s+n,0)/valid.length:null}
function urRating(n){return n===null?'Not observed':n.toFixed(2)+' / 5'}
function urSummaryCards(items){return `<div class="stats urstats">${items.map(([label,n,h])=>`<div class="stat"><div class="top">${label}<span class="symbol">◈</span></div><strong>${n}</strong><small>${h}</small></div>`).join('')}</div>`}
function pmsEllipsisIcon(){return '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg>'}
function pmsRowActions(label,action,items=[]){return `<div class="uractions pms-row-actions"><button type="button" class="textbtn" onclick="${esc(action)}">${esc(label)}</button>${items.length?`<button type="button" class="pms-row-more" aria-label="More actions" aria-haspopup="menu" onclick="pmsOpenRowMenu(event,${esc(JSON.stringify(items))})">${pmsEllipsisIcon()}</button>`:''}</div>`}
function pmsOpenRowMenu(event,items){
 let menu=$('#pmsRowActionMenu');if(!menu){menu=document.createElement('div');menu.id='pmsRowActionMenu';menu.setAttribute('popover','auto');menu.setAttribute('role','menu');document.body.appendChild(menu)}
 menu.innerHTML=items.map(item=>`<button type="button" role="menuitem" onclick="document.querySelector('#pmsRowActionMenu').hidePopover();${esc(item.action)}">${esc(item.label)}</button>`).join('');
 const box=event.currentTarget.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(box.right-190,window.innerWidth-198))+'px';menu.style.top=Math.max(8,Math.min(box.bottom+4,window.innerHeight-items.length*40-16))+'px';menu.showPopover();
}
function pmsGoalActions(g){const editable=viewRole!=='Employee'||pmsGoalStatus(g)!=='Completed';return pmsRowActions('View',`pmsViewGoal(${JSON.stringify(g.id)})`,editable?[{label:viewRole==='Employee'&&!pmsOwnGoal(g)?'Update Progress':'Edit Goal',action:`roleGoal(${JSON.stringify(g.id)})`}]:[])}
function pmsViewGoal(id){
 const g=scopedGoals().find(g=>String(g.id)===String(id));if(!g)return;
 const ms=pmsGoalMilestones(g),configure=typeof pmsCanConfigureGoal==='function'?pmsCanConfigureGoal(g):viewRole!=='Employee'||pmsOwnGoal(g)&&pmsGoalStatus(g)!=='Completed',update=typeof pmsCanUpdateGoalProgress==='function'?pmsCanUpdateGoalProgress(g):viewRole==='Employee'&&pmsGoalStatus(g)!=='Completed';
 const creator=typeof pmsGoalCreatorName==='function'?pmsGoalCreatorName(g):g.assignedBy||'Not recorded';
 modal('Goal Details',g.name,`<div class="modalbody"><p>${esc(g.description||'No description added.')}</p><div class="formgrid">${[['Created by',creator],['Owned by',g.employee],['Category',g.category],['Deadline',date(g.due)],['Status',pmsGoalStatus(g)]].map(([l,v])=>`<div><small>${l}</small><b>${esc(v)}</b></div>`).join('')}</div><div class="pms-goal-detail-progress">${progress(g.progress)}</div><h3>Milestones</h3>${ms.length?ms.map(m=>`<p>${m.done?'✓':'○'} ${esc(m.title)}${m.due?' · '+date(m.due):''}</p>`).join(''):'<p>No milestones added yet.</p>'}</div>`,`<button onclick="closeModal()">Close</button>${configure||update?`<button class="primary" onclick='roleGoal(${JSON.stringify(g.id)})'>${configure?'Edit Goal':'Update Progress'}</button>`:''}`);
}

function urPageHead(title,description,action=''){return head(title,description,action)}
function urGo(fn){if(urDirty){urPending=fn;modal('Leave without saving?','Your unsaved changes will be discarded.',`<div class="modalbody"><p>Save your draft before leaving if you want to keep these changes.</p></div>`,`<button onclick="closeModal()">Keep editing</button><button class="primary" onclick="urDirty=false;closeModal();urPending()">Discard changes</button>`)}else fn()}
function urGoTab(t){urGo(()=>{page='Reviews';urTab=t;urScreen='list';urPreview=false;render()})}
function urEmpty(title,text,action=''){return `<div class="empty"><div class="emptyicon">▤</div><h2>${title}</h2><p>${text}</p>${action}</div>`}
function urSelect(label,key,values,selected,onchange){return `<label class="urfilter"><span>${label}</span><select aria-label="${label}" onchange="${onchange||`urFilter.${key}=this.value;urDrawReviews()`}">${values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
function urReviewList(){const all=UR.assignments.filter(urVisible),pending=all.filter(a=>['Not Started','Overdue'].includes(urEffective(a))).length;return urPageHead('Reviews','View, complete, and manage employee performance evaluations.')+urSummaryCards([['Total Reviews',all.length,'Individual evaluator assignments'],['Pending Reviews',pending,'Not started or overdue'],['In Progress',all.filter(a=>a.state==='In Progress'&&urEffective(a)!=='Overdue').length,'Saved drafts'],['Completed Reviews',all.filter(a=>a.state==='Completed').length,'Finalized review workflows']])+`<section class="panel pms-review-list"><div class="tabs">${['All Reviews','My Reviews',...(viewRole==='Manager'?['Team Reviews']:[]),'Completed'].map(t=>`<button class="${urFilter.view===t?'selected':''}" onclick="urFilter.view='${t}';urDrawReviews();this.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===this))">${t}</button>`).join('')}</div><div class="toolbar urtoolbar"><label class="urfilter ursearch"><span>Search</span><input class="search" aria-label="Search review assignments" placeholder="Employee or evaluator…" value="${esc(urFilter.q)}" oninput="urFilter.q=this.value;urDrawReviews()"></label>${urSelect('Review Cycle','cycle',['All cycles',...UR.cycles.filter(c=>all.some(a=>a.cycle===c.id)).map(c=>c.name)],urFilter.cycle)}${urSelect('Review Type','type',['All types',...urTypes],urFilter.type)}${urSelect('Department','department',['All departments',...new Set(data.employees.map(e=>e[3]))],urFilter.department)}${urSelect('Status','status',['All statuses',...urStatus],urFilter.status)}<button class="textbtn" onclick="urFilter={view:'All Reviews',q:'',cycle:'All cycles',type:'All types',department:'All departments',status:'All statuses'};render()">Clear</button></div><div class="tablewrap"><table><thead><tr><th>EMPLOYEE</th><th>REVIEW CYCLE</th><th>REVIEW TYPE</th><th>REVIEWER</th><th>DUE DATE</th><th>STATUS</th></tr></thead><tbody id="urReviewRows"></tbody></table></div><div class="tablefoot"><span id="urReviewCount"></span><span>Dates follow the sample workspace calendar · ${date(urToday)}</span></div></section>`}
function urDrawReviews(){const rows=UR.assignments.filter(urVisible).filter(a=>{const c=urCycle(a.cycle),p=urPerson(a.subject),reviewer=urAnon(a)&&a.reviewer!==urUser()?'Anonymous '+a.type:urPerson(a.reviewer).name;return (urFilter.view!=='My Reviews'||a.reviewer===urUser())&&(urFilter.view!=='Team Reviews'||urTeam(a.subject))&&(urFilter.view!=='Completed'||a.state==='Completed')&&(`${p.name} ${reviewer}`.toLowerCase().includes(urFilter.q.toLowerCase()))&&(urFilter.cycle==='All cycles'||c.name===urFilter.cycle)&&(urFilter.type==='All types'||a.type===urFilter.type)&&(urFilter.department==='All departments'||p.department===urFilter.department)&&(urFilter.status==='All statuses'||urEffective(a)===urFilter.status)});$('#urReviewRows').innerHTML=rows.map(a=>{const c=urCycle(a.cycle),own=a.reviewer===urUser(),editable=urCanEdit(a),read=urCanRead(a);return `<tr data-pms-record="review" data-pms-id="${esc(a.id)}" tabindex="0" aria-label="Open review for ${esc(urPerson(a.subject).name)}"><td>${urDisplayPerson(a.subject)}</td><td class="urwrap">${esc(c.name)}</td><td><span class="pill">${a.type}</span></td><td>${urAnon(a)&&!own?`<span class="anonymous">♧ Anonymous ${a.type.toLowerCase()}</span>`:esc(urPerson(a.reviewer).name)+(own?'<small>Assigned to you</small>':'')}</td><td>${date(a.deadline)}</td><td>${urBadge(urEffective(a))}</td></tr>`}).join('')||'<tr><td colspan="6">'+urEmpty('No review assignments','Try another filter or ask HR to launch a cycle for you.')+'</td></tr>';$('#urReviewCount').textContent=`${rows.length} individual assignments`}
function urQuestionFields(t,answers={},readOnly=false,preview=false){return t.sections.map(section=>`<section class="urformsection"><div class="ursectiontitle"><span>${String(t.sections.indexOf(section)+1).padStart(2,'0')}</span><div><h2>${esc(section)}</h2><small>${t.questions.filter(q=>q.section===section).length} question${t.questions.filter(q=>q.section===section).length===1?'':'s'}</small></div></div>${t.questions.filter(q=>q.section===section).map(q=>{const value=answers[q.id]??'',event=`onchange="${preview?'urPreviewAnswers':'urAnswers'}['${q.id}']=this.value;${preview?'':'urDirty=true;urUpdateCompletion()'}"`,disable=readOnly?'disabled':'';return `<div class="urquestion"><label for="answer-${q.id}">${esc(q.title)} ${q.required?'<span class="required">*</span>':'<span class="urmuted">Optional</span>'}</label>${q.description?`<p>${esc(q.description)}</p>`:''}${q.type==='Rating'?`<div class="ratings">${['Never','Rarely','Sometimes','Often','Always'].map((l,i)=>`<label><input type="radio" name="${q.id}" value="${i+1}" ${String(value)===String(i+1)?'checked':''} ${disable} ${event}><span><b>${i+1}</b>${l}</span></label>`).join('')}${q.notObserved?`<label class="norating"><input type="radio" name="${q.id}" value="NO" ${value==='NO'?'checked':''} ${disable} ${event}><span>Not Observed</span></label>`:''}</div>`:q.type==='Choice'?`<select id="answer-${q.id}" aria-label="${esc(q.title)}" ${disable} ${event}><option value="">Select an answer</option>${q.options.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:q.type==='Short'?`<input id="answer-${q.id}" maxlength="500" value="${esc(value)}" ${readOnly?'readonly':''} aria-label="${esc(q.title)}" oninput="${preview?'urPreviewAnswers':'urAnswers'}['${q.id}']=this.value;${preview?'':'urDirty=true;urUpdateCompletion()'}">`:`<textarea id="answer-${q.id}" rows="3" maxlength="5000" ${readOnly?'readonly':''} aria-label="${esc(q.title)}" oninput="${preview?'urPreviewAnswers':'urAnswers'}['${q.id}']=this.value;${preview?'':'urDirty=true;urUpdateCompletion()'}">${esc(value)}</textarea>`}</div>`}).join('')}</section>`).join('')}
let urPreviewAnswers={};
function urCompletion(t,answers){const required=t.questions.filter(q=>q.required);return {answered:required.filter(q=>String(answers[q.id]??'').trim()).length,total:required.length}}
function urUpdateCompletion(){const a=UR.assignments.find(a=>a.id===urDetail);if(!a)return;const n=urCompletion(a.template,urAnswers),pct=n.total?Math.round(n.answered/n.total*100):100;if($('#urCompletion'))$('#urCompletion').innerHTML=`<span>${n.answered} / ${n.total} required questions answered</span>${progress(pct)}`}
function urOpenReview(id){const a=UR.assignments.find(a=>a.id===id);if(!a||!urVisible(a)||!urCanRead(a))return;urGo(()=>{page='Reviews';urTab='Reviews';urScreen='review';urDetail=id;urAnswers=urClone(a.answers);urDirty=false;render()})}
function urReviewDetail(){const a=UR.assignments.find(a=>a.id===urDetail);if(!a||!urCanRead(a))return urEmpty('Review unavailable','This response is outside your visibility permissions.');const c=urCycle(a.cycle),p=urPerson(a.subject),editable=urCanEdit(a);return urPageHead('Review Details',`${p.name} · ${p.position}`,`<button onclick="urGoTab('Reviews')">← Back to Reviews</button>`)+`<div class="urdetailmeta panel"><div>${urDisplayPerson(a.subject)}</div>${[['Department',p.department],['Review Cycle',c.name],['Review Type',a.type],['Due Date',date(a.deadline)]].map(([l,v])=>`<div><small>${l}</small><b>${esc(v)}</b></div>`).join('')}<div><small>Status</small>${urBadge(urEffective(a))}</div></div><div class="urformlayout"><div class="urformmain"><div class="panel urintro"><h2>${esc(a.template.name)} <span class="pill">v${a.template.version}</span></h2><p>${esc(a.template.description)}</p></div>${!editable?'<div class="notice">This response is read only. Submitted responses can only be reopened by HR before cycle finalization and release.</div>':''}${urAnon(a)?'<div class="notice">Your feedback is grouped anonymously. Results are withheld until the minimum response threshold is met. Avoid identifying yourself in written feedback.</div>':''}<div id="urValidation" role="alert" class="urerror"></div>${urQuestionFields(a.template,urAnswers,!editable)}</div><aside class="urformside"><section class="panel"><h2>Review completion</h2><div id="urCompletion"></div><small>Not Observed is a valid answer and is excluded from rating averages.</small><hr><p>${editable?'Save your progress, then submit when you are ready.':'Submitted and completed responses are locked.'}</p>${editable?`<button onclick="urSaveResponse()">Save as Draft</button><button class="primary" onclick="urConfirmSubmit()">Submit Review</button>`:''}${urHr()&&a.state==='Submitted'&&!c.released&&c.status==='Active'?`<button onclick="urReopen('${a.id}')">Reopen response</button>`:''}${urCanResult(c,a.subject)?`<button onclick="urOpenResult('${c.id}','${a.subject}')">View Results</button>`:''}</section></aside></div>`}
function urSaveResponse(){const a=UR.assignments.find(a=>a.id===urDetail);if(!a||!urCanEdit(a))return;a.answers=urClone(urAnswers);a.state='In Progress';a.updated=urToday;urDirty=false;urAudit('Draft saved: '+a.id);render();toast('Review draft saved')}
function urConfirmSubmit(){const a=UR.assignments.find(a=>a.id===urDetail);if(!a||!urCanEdit(a))return;const missing=a.template.questions.filter(q=>q.required&&!String(urAnswers[q.id]??'').trim());if(missing.length){$('#urValidation').innerHTML=`Please answer ${missing.length} required question${missing.length>1?'s':''}: ${missing.map(q=>esc(q.title)).join('; ')}`;$('#urValidation').scrollIntoView({block:'center',behavior:'smooth'});return}modal('Submit this review?','Your response will become read only.',`<div class="modalbody"><p>You have answered all required questions. Submitted means your response is received; HR finalizes the cycle separately.</p></div>`,`<button onclick="closeModal()">Keep editing</button><button class="primary" onclick="urSubmitResponse()">Confirm submission</button>`)}
function urSubmitResponse(){const a=UR.assignments.find(a=>a.id===urDetail);if(!a||!urCanEdit(a))return;a.answers=urClone(urAnswers);a.state='Submitted';a.submitted=urToday;a.updated=urToday;urDirty=false;urAudit('Response submitted: '+a.id);closeModal();render();toast('Review submitted successfully')}
function urReopen(id){const a=UR.assignments.find(a=>a.id===id),c=a&&urCycle(a.cycle);if(!urHr()||!a||a.state!=='Submitted'||c.status!=='Active'||c.released)return;modal('Reopen submitted review?','The assigned evaluator will be able to edit this response again.',`<div class="modalbody"><p>The response returns to In Progress and must be submitted again before the cycle can be finalized.</p></div>`,`<button onclick="closeModal()">Cancel</button><button class="primary" onclick="UR.assignments.find(a=>a.id==='${id}').state='In Progress';urAudit('Response reopened: ${id}');closeModal();render();toast('Review reopened')">Reopen review</button>`)}
function urTemplateList(){if(!urHr())return urPageHead('Review Templates','Create and manage reusable forms for employee performance evaluations.')+urEmpty('Managed by HR','Templates are managed by HR. Your assigned questionnaire is available under Reviews.','<button onclick="urGoTab(\'Reviews\')">Go to Reviews</button>');return urPageHead('Review Templates','Create and manage reusable forms for employee performance evaluations.','<button class="gradient" onclick="urEditTemplate()">＋ Create Template</button>')+(UR.draftCycle?`<div class="notice urresumebar">Your cycle setup is saved. <button class="textbtn" onclick="urStartWizard()">Resume cycle setup →</button></div>`:'')+`<section class="panel"><div class="panelhead"><div><h2>Reusable review forms</h2><p>Publish a template to make it available in cycle setup. Launched assignments keep an immutable copy.</p></div><span class="pill blue">${UR.templates.length} templates</span></div><div class="toolbar"><input class="search" aria-label="Search templates" placeholder="Search templates…" value="${esc(urTemplateFilter)}" oninput="urTemplateFilter=this.value;urDrawTemplates()"></div><div class="tablewrap"><table><thead><tr><th>TEMPLATE NAME</th><th>DESCRIPTION</th><th>REVIEW TYPE</th><th>QUESTIONS</th><th>LAST UPDATED</th><th>STATUS</th></tr></thead><tbody id="urTemplateRows"></tbody></table></div></section>`}
function urDrawTemplates(){if(!urHr())return;$('#urTemplateRows').innerHTML=UR.templates.filter(t=>(t.name+' '+t.description).toLowerCase().includes(urTemplateFilter.toLowerCase())).map(t=>`<tr><td><b>${esc(t.name)}</b><small>Version ${t.version} · ${esc(t.category)}</small></td><td class="urwrap">${esc(t.description)}</td><td>${t.type}</td><td>${t.questions.length}</td><td>${date(t.updated)}</td><td>${urBadge(t.status)}</td><td><div class="uractions"><button class="textbtn" onclick="urViewTemplate('${t.id}')">View</button><button class="textbtn" onclick="urEditTemplate('${t.id}')">Edit</button><button class="textbtn" onclick="urDuplicateTemplate('${t.id}')">Duplicate</button><button class="textbtn" onclick="urPreviewTemplate('${t.id}')">Preview</button>${t.status!=='Archived'?`<button class="textbtn" onclick="urArchiveTemplate('${t.id}')">Archive</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="7">'+urEmpty('No templates found','Change your search or create your first review template.')+'</td></tr>'}
function urUsedTemplate(id){return UR.assignments.some(a=>a.template.id===id)||UR.cycles.some(c=>['Active','Scheduled','Completed'].includes(c.status)&&Object.values(c.templates).includes(id))}
function urEditTemplate(id){if(!urHr())return;urGo(()=>{page='Reviews';const t=UR.templates.find(t=>t.id===id);urEditor=t?urClone(t):urTemplate('','Self','General Performance',[urQuestion('','Rating')],'Draft');urEditor.isNew=!t;if(t&&(urUsedTemplate(id)||t.status==='Published')){urEditor.id=urUid('tpl');urEditor.version=t.version+1;urEditor.status='Draft';urEditor.isNew=true;urEditor.original=t.id;toast('Editing a new version. Existing assignments stay unchanged.')}urTab='Templates';urScreen='builder';urDirty=false;urPreview=false;render()})}
function urDuplicateTemplate(id){if(!urHr())return;const t=UR.templates.find(t=>t.id===id),copy={...urClone(t),id:urUid('tpl'),name:t.name+' (Copy)',status:'Draft',updated:urToday,version:1};UR.templates.push(copy);urAudit('Template duplicated: '+id);render();toast('Draft copy created')}
function urArchiveTemplate(id){if(!urHr())return;modal('Archive this template?','Existing cycles and review responses will stay unchanged.',`<div class="modalbody"><p>Archived templates cannot be selected for future cycle launches.</p></div>`,`<button onclick="closeModal()">Cancel</button><button class="primary" onclick="UR.templates.find(t=>t.id==='${id}').status='Archived';if(urEditor?.id==='${id}')urEditor.status='Archived';urAudit('Template archived: ${id}');closeModal();render();toast('Template archived')">Archive template</button>`)}
function urViewTemplate(id){const t=UR.templates.find(t=>t.id===id);if(!t||!urHr())return;urGo(()=>{page='Reviews';urEditor=urClone(t);urPreview=true;urPreviewAnswers={};urScreen='templateView';urTab='Templates';render()})}
function urPreviewTemplate(id){const t=UR.templates.find(t=>t.id===id);if(!t||!urHr())return;urPreviewAnswers={};modal('Template preview',`${esc(t.name)} · version ${t.version}`,`<div class="modalbody urpreviewmodal"><div class="notice">Preview only. These answers are not saved or submitted.</div>${urQuestionFields(t,{},false,true)}</div>`,`<button onclick="closeModal()">Close Preview</button>`)}
function urPreviewBuilder(){urPreview=!urPreview;urPreviewAnswers={};render()}
function pmsTemplateBuilderHeader(t,view){
 const preview=view||urPreview;
 const back=view?`<button class="pms-back-link" onclick="urGoTab('Templates')">← Back to Templates</button>`:preview?'<button class="pms-back-link" onclick="urPreviewBuilder()">← Back to Builder</button>':`<button class="pms-back-link" onclick="urGoTab('Templates')">← Back to Templates</button>`;
 const detailActions=view?`<button class="primary" onclick="urEditTemplate('${t.id}')">Edit</button><button onclick="urPreviewTemplate('${t.id}')">Preview</button>${pmsRowActions('Duplicate',`urDuplicateTemplate('${t.id}')`,t.status!=='Archived'?[{label:'Archive',action:`urArchiveTemplate('${t.id}')`}]:[])}`:'';
 const actions=view?detailActions:preview?'':`<button onclick="urPreviewBuilder()"><svg class="pms-eye-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>Preview</button><button onclick="urSaveTemplate('Draft')">Save as Draft</button><button class="primary" onclick="urSaveTemplate('Published')">Publish Template</button>`;
 return `<div class="pagehead pms-nested-head"><div class="pms-back-row">${back}</div><div class="pms-nested-title-row"><div><h1>${view?'Template Details':preview?'Template Preview':t.isNew?'Create Review Template':'Edit Review Template'}</h1><p>${view?esc(t.name):preview?'Preview how the questionnaire will appear to respondents.':'Build a reusable form with clear questions and consistent rating labels.'}</p></div>${actions?`<div class="pms-page-actions">${actions}</div>`:''}</div></div>`;
}
function urBuilder(){if(!urHr()||!urEditor)return urEmpty('Template unavailable','HR access is required.');const t=urEditor,view=urScreen==='templateView';return pmsTemplateBuilderHeader(t,view)+`<div class="urbuilder">${!urPreview?`<small class="pms-builder-status">${t.status==='Draft'?'Draft':'Editing'} · ${t.questions.length} question${t.questions.length===1?'':'s'}</small>`:''}${urPreview?`<div class="panel urintro"><span class="pill blue">Respondent preview</span><h2 style="margin-top:12px">${esc(t.name||'Untitled template')}</h2><p>${esc(t.description)}</p><small>Preview answers are not saved.</small></div>${urQuestionFields(t,urPreviewAnswers,false,true)}`:`${t.original?'<div class="notice">You are creating version '+t.version+'. Published versions and historical responses remain unchanged.</div>':''}<section class="panel urbuilderinfo"><div class="eyebrow">TEMPLATE INFORMATION</div><label>Template Name <span class="required">*</span><input maxlength="120" placeholder="e.g. Quarterly Performance Review" value="${esc(t.name)}" oninput="urEditor.name=this.value;urDirty=true"></label><label>Description / Instructions<textarea rows="3" maxlength="2000" oninput="urEditor.description=this.value;urDirty=true">${esc(t.description)}</textarea></label><div class="formgrid"><label>Template Category<select onchange="urEditor.category=this.value;urDirty=true">${['General Performance','Self-Assessment','Manager Evaluation','Peer Feedback','360° Feedback','Probationary Evaluation'].map(c=>`<option ${t.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Review Type<select onchange="urEditor.type=this.value;urDirty=true">${urTypes.map(c=>`<option ${t.type===c?'selected':''}>${c}</option>`).join('')}</select></label></div></section>${t.sections.map((section,si)=>`<section class="urbuildsection"><div class="ursectioneditor"><span class="ursectionnumber">${si+1}</span><label>Section title<input aria-label="Section ${si+1} title" value="${esc(section)}" onchange="urRenameSection(${si},this.value)"></label><div class="uractions"><button title="Move section up" ${si===0?'disabled':''} onclick="urMoveSection(${si},-1)">↑</button><button title="Move section down" ${si===t.sections.length-1?'disabled':''} onclick="urMoveSection(${si},1)">↓</button></div></div>${t.questions.filter(q=>q.section===section).map((q,qi)=>urQuestionCard(q,qi)).join('')}<button class="uraddquestion" onclick="urAddQuestion(${si})">＋ Add question to section</button></section>`).join('')}<button class="uraddsection" onclick="urAddSection()">＋ Add Section</button><div id="urBuilderError" class="urerror" role="alert"></div>`}</div>`}
function urQuestionCard(q,index){const group=urEditor.questions.filter(x=>x.section===q.section);return `<div class="panel urquestioncard"><div class="urquestioncardhead"><span>QUESTION ${index+1}</span><div class="uractions"><button title="Move question up" ${index===0?'disabled':''} onclick="urMoveQuestion('${q.id}',-1)">↑</button><button title="Move question down" ${index===group.length-1?'disabled':''} onclick="urMoveQuestion('${q.id}',1)">↓</button><button onclick="urDuplicateQuestion('${q.id}')">Duplicate</button><button onclick="urDeleteQuestion('${q.id}')">Delete</button></div></div><label>Question Title <span class="required">*</span><input aria-label="Question title" maxlength="300" value="${esc(q.title)}" placeholder="Ask about a specific behavior or outcome…" oninput="urSetQuestion('${q.id}','title',this.value)"></label><label>Optional Description<input value="${esc(q.description)}" maxlength="500" oninput="urSetQuestion('${q.id}','description',this.value)"></label><div class="urquestionconfig"><label>Question Type<select aria-label="Question type" onchange="urChangeType('${q.id}',this.value)">${[['Rating','Rating Scale (1–5)'],['Short','Short Answer'],['Paragraph','Paragraph'],['Choice','Multiple Choice']].map(([v,l])=>`<option value="${v}" ${q.type===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="urcheck"><input type="checkbox" ${q.required?'checked':''} onchange="urSetQuestion('${q.id}','required',this.checked)">Required</label>${q.type==='Rating'?`<label class="urcheck"><input type="checkbox" ${q.notObserved?'checked':''} onchange="urSetQuestion('${q.id}','notObserved',this.checked)">Allow Not Observed</label>`:''}</div>${q.type==='Rating'?'<div class="urscalepreview">1 Never <span>2 Rarely</span><span>3 Sometimes</span><span>4 Often</span><span>5 Always</span></div>':q.type==='Choice'?`<div class="uroptions">${q.options.map((o,i)=>`<div><span>○</span><input aria-label="Answer option ${i+1}" value="${esc(o)}" maxlength="150" oninput="urSetOption('${q.id}',${i},this.value)"><button aria-label="Remove option ${i+1}" onclick="urRemoveOption('${q.id}',${i})">×</button></div>`).join('')}<button class="textbtn" onclick="urAddOption('${q.id}')">＋ Add answer option</button></div>`:'<div class="uranswerplaceholder">'+(q.type==='Short'?'Short answer text':'Long answer text')+'</div>'}</div>`}
function urSetQuestion(id,key,value){const q=urEditor.questions.find(q=>q.id===id);q[key]=value;urDirty=true}
function urChangeType(id,type){const q=urEditor.questions.find(q=>q.id===id);q.type=type;if(type==='Choice'&&!q.options.length)q.options=['Option 1','Option 2'];q.notObserved=type==='Rating';urDirty=true;render()}
function urAddQuestion(si){urEditor.questions.push(urQuestion('','Rating',urEditor.sections[si]));urDirty=true;render()}
function urDuplicateQuestion(id){const i=urEditor.questions.findIndex(q=>q.id===id),q=urClone(urEditor.questions[i]);q.id=urUid('q');urEditor.questions.splice(i+1,0,q);urDirty=true;render()}
function urDeleteQuestion(id){urEditor.questions=urEditor.questions.filter(q=>q.id!==id);urDirty=true;render()}
function urMoveQuestion(id,by){const q=urEditor.questions.find(q=>q.id===id),siblings=urEditor.questions.filter(x=>x.section===q.section),i=siblings.indexOf(q),target=siblings[i+by];if(!target)return;const a=urEditor.questions.indexOf(q),b=urEditor.questions.indexOf(target);[urEditor.questions[a],urEditor.questions[b]]=[urEditor.questions[b],urEditor.questions[a]];urDirty=true;render()}
function urAddSection(){let name='Section '+(urEditor.sections.length+1);while(urEditor.sections.includes(name))name+=' (new)';urEditor.sections.push(name);urDirty=true;render()}
function urRenameSection(i,name){name=name.trim();if(!name||urEditor.sections.some((s,j)=>s===name&&j!==i)){toast('Use a unique, non-empty section title');render();return}const old=urEditor.sections[i];urEditor.sections[i]=name;urEditor.questions.forEach(q=>{if(q.section===old)q.section=name});urDirty=true;render()}
function urMoveSection(i,by){if(i+by<0||i+by>=urEditor.sections.length)return;[urEditor.sections[i],urEditor.sections[i+by]]=[urEditor.sections[i+by],urEditor.sections[i]];urDirty=true;render()}
function urSetOption(id,i,value){urEditor.questions.find(q=>q.id===id).options[i]=value;urDirty=true}
function urAddOption(id){urEditor.questions.find(q=>q.id===id).options.push('');urDirty=true;render()}
function urRemoveOption(id,i){urEditor.questions.find(q=>q.id===id).options.splice(i,1);urDirty=true;render()}
function urTemplateErrors(t,publish){const errors=[];if(!t.name.trim())errors.push('Enter a template name.');if(publish){if(!t.questions.length)errors.push('Add at least one question.');if(t.sections.some(s=>!t.questions.some(q=>q.section===s)))errors.push('Add at least one question to every section.');if(t.questions.some(q=>!q.title.trim()))errors.push('Enter a title for each question.');for(const q of t.questions.filter(q=>q.type==='Choice'))if(q.options.length<2||q.options.some(o=>!o.trim())||new Set(q.options.map(o=>o.trim().toLowerCase())).size!==q.options.length)errors.push('Multiple-choice questions need at least two distinct, non-empty options.')}return [...new Set(errors)]}
function urSaveTemplate(state){if(!urHr())return;const errors=urTemplateErrors(urEditor,state==='Published');if(errors.length){if(urPreview){urPreview=false;render()}$('#urBuilderError').textContent=errors.join(' ');return}const t=urClone(urEditor);delete t.isNew;delete t.original;t.status=state;t.name=t.name.trim();t.updated=urToday;const i=UR.templates.findIndex(x=>x.id===t.id);if(i>=0)UR.templates[i]=t;else UR.templates.push(t);urDirty=false;urAudit('Template '+state.toLowerCase()+': '+t.id);urScreen='list';urTab='Templates';urPreview=false;render();toast(state==='Published'?'Template published':'Template draft saved')}
function urCycleList(){const cs=UR.cycles.filter(c=>urHr()||UR.assignments.some(a=>a.cycle===c.id&&urVisible(a))||c.participants.some(id=>id===urUser()||viewRole==='Manager'&&urTeam(id)));return urPageHead('Review Cycles','Plan, launch, and monitor employee performance review cycles.',urHr()?'<button class="gradient" onclick="urStartWizard(null,true)">＋ Create Cycle</button>':'')+urSummaryCards([['Total Cycles',cs.length,'Cycles visible to your role'],['Draft Cycles',cs.filter(c=>c.status==='Draft').length,'Configuration in progress'],['Active Cycles',cs.filter(c=>c.status==='Active').length,'Accepting evaluator responses'],['Completed Cycles',cs.filter(c=>c.status==='Completed').length,'Finalized workflows']])+(urHr()&&UR.draftCycle?'<div class="notice urresumebar">You have a saved setup in progress. <button class="textbtn" onclick="urStartWizard()">Resume cycle setup →</button></div>':'')+`<section class="panel"><div class="panelhead"><div><h2>Cycle register</h2><p>Templates define the questions. Cycles generate individual review assignments.</p></div></div><div class="toolbar urtoolbar"><label class="urfilter ursearch"><span>Search</span><input class="search" aria-label="Search review cycles" placeholder="Search cycle name…" value="${esc(urCycleFilter.q)}" oninput="urCycleFilter.q=this.value;urDrawCycles()"></label>${urSelect('Cycle status','', ['All statuses','Draft','Scheduled','Active','Completed','Cancelled'],urCycleFilter.status,'urCycleFilter.status=this.value;urDrawCycles()')}${urSelect('Cycle review type','',['All types','Standard Performance Review','360° Feedback','Probationary Review','Project-Based Review'],urCycleFilter.type,'urCycleFilter.type=this.value;urDrawCycles()')}${urSelect('Review period','',['All periods',...new Set(cs.map(c=>c.periodStart+' — '+c.periodEnd))],urCycleFilter.period,'urCycleFilter.period=this.value;urDrawCycles()')}</div><div class="tablewrap"><table><thead><tr><th>CYCLE NAME</th><th>REVIEW TYPE</th><th>REVIEW PERIOD</th><th>PARTICIPANTS</th><th>PROGRESS</th><th>DEADLINE</th><th>STATUS</th></tr></thead><tbody id="urCycleRows"></tbody></table></div></section>`}
function urCycleAssignments(c){return UR.assignments.filter(a=>a.cycle===c.id)}
function urDrawCycles(){const cs=UR.cycles.filter(c=>urHr()||c.participants.some(id=>id===urUser()||viewRole==='Manager'&&urTeam(id))||UR.assignments.some(a=>a.cycle===c.id&&a.reviewer===urUser())).filter(c=>c.name.toLowerCase().includes(urCycleFilter.q.toLowerCase())&&(urCycleFilter.status==='All statuses'||c.status===urCycleFilter.status)&&(urCycleFilter.type==='All types'||c.type===urCycleFilter.type)&&(urCycleFilter.period==='All periods'||c.periodStart+' — '+c.periodEnd===urCycleFilter.period));$('#urCycleRows').innerHTML=cs.map(c=>{const all=urCycleAssignments(c).filter(urVisible),done=all.filter(a=>a.state==='Completed').length,submitted=all.filter(a=>a.state==='Submitted').length;return `<tr data-pms-record="cycle" data-pms-id="${esc(c.id)}" tabindex="0" aria-label="Open cycle ${esc(c.name)}"><td class="urwrap"><button class="textbtn" onclick="urOpenCycle('${c.id}')"><b>${esc(c.name)}</b></button>${c.released?'<small>Results released</small>':''}</td><td>${esc(c.type)}</td><td>${date(c.periodStart)}<small>to ${date(c.periodEnd)}</small></td><td>${urHr()?c.participants.length:c.participants.filter(id=>id===urUser()||viewRole==='Manager'&&urTeam(id)).length}</td><td>${done} / ${all.length}<small>${submitted} submitted${urHr()?'':' · visible assignments'}</small>${progress(all.length?Math.round(done/all.length*100):0)}</td><td>${date(c.deadline)}</td><td>${urBadge(c.status)}</td></tr>`}).join('')||'<tr><td colspan="7">'+urEmpty('No cycles found','Try another filter. HR can create a new cycle from here.')+'</td></tr>'}
function urNewCycle(){return {id:urUid('cycle'),name:'',description:'',type:'Standard Performance Review',periodStart:'2026-07-01',periodEnd:'2026-09-30',start:'2026-10-19',deadline:'2026-11-13',participants:[],groups:['Self','Manager'],evaluators:[],templates:{},anonymousPeer:true,anonymousUpward:true,threshold:3,status:'Draft',released:false,finalComments:{},created:urToday}}
let urEmployeeSearch='',urEmployeeDept='All departments';
function urStartWizard(id,fresh=false){if(!urHr())return;urGo(()=>{page='Reviews';urWizard=id?urClone(urCycle(id)):!fresh&&UR.draftCycle?urClone(UR.draftCycle):urNewCycle();urStep=urWizard.savedStep||1;urWizard.status='Draft';urScreen='wizard';urTab='Cycles';urDirty=false;urEmployeeSearch='';urEmployeeDept='All departments';render()})}
function urSetCycle(k,v){urWizard[k]=v;urDirty=true}
function urCycleValidation(c,step=5){const e=[];if(!c.name.trim())e.push('Enter a cycle name.');if(!c.periodStart||!c.periodEnd||c.periodStart>c.periodEnd)e.push('Review period start must be on or before its end.');if(!c.start||!c.deadline||c.start>c.deadline)e.push('Cycle start must be on or before the submission deadline.');if(step>=2&&!c.participants.length)e.push('Select at least one employee.');if(step>=3){if(!c.groups.length)e.push('Enable at least one evaluator type.');for(const subject of c.participants)for(const type of c.groups)if(!c.evaluators.some(a=>a.subject===subject&&a.type===type))e.push(`${urPerson(subject).name} needs a ${type} evaluator.`);const keys=c.evaluators.map(a=>a.subject+'|'+a.type+'|'+a.reviewer);if(new Set(keys).size!==keys.length)e.push('Remove duplicate evaluator assignments.');if(c.evaluators.some(a=>!c.participants.includes(a.subject)||!urPeople().some(p=>p.id===a.reviewer)))e.push('Every assignment needs a valid employee and evaluator.');if(c.evaluators.some(a=>a.type==='Self'?a.subject!==a.reviewer:a.subject===a.reviewer))e.push('Self evaluators must be the employee; other evaluator types must be someone else.');if(!Number.isInteger(+c.threshold)||+c.threshold<2||+c.threshold>10)e.push('Anonymous response threshold must be a whole number from 2 to 10.');}if(step>=4){for(const type of c.groups){const t=UR.templates.find(t=>t.id===c.templates[type]);if(!t||t.status!=='Published')e.push('Choose a published template for '+type+'.');else if(urTemplateErrors(t,true).length)e.push('The '+type+' template contains invalid questions.')}}return [...new Set(e)]}
function urWizardStep(step){if(step>urStep){const errors=urCycleValidation(urWizard,urStep);if(errors.length){$('#urWizardError').textContent=errors.join(' ');return}}urStep=step;render()}
function urWizardPage(){if(!urHr()||!urWizard)return '';const c=urWizard;return urPageHead('Create Review Cycle','Configure participants, evaluator perspectives, forms, and timelines.',`<button onclick="urGoTab('Cycles')">← Back to Cycles</button>`)+`<div class="urstepper">${['General Information','Select Employees','Assign Evaluators','Select Templates','Review & Launch'].map((s,i)=>`<button class="${urStep===i+1?'active':urStep>i+1?'done':''}" onclick="urWizardStep(${i+1})"><span>${urStep>i+1?'✓':i+1}</span>${s}</button>`).join('')}</div><section class="panel urwizardpanel"><div class="panelhead"><div><div class="eyebrow">STEP ${urStep} OF 5</div><h2>${['General Information','Select Employees','Assign Evaluators','Select Templates','Review & Launch'][urStep-1]}</h2><p>${['Define the period being evaluated and when responses will be collected.','Choose the people who will receive evaluations.','Assign one or more evaluators for each enabled perspective.','Reuse published forms for each evaluator group.','Confirm the configuration before creating assignments.'][urStep-1]}</p></div></div><div class="urwizardbody">${urStep===1?`<div class="formgrid"><label class="full">Cycle Name <span class="required">*</span><input maxlength="120" required value="${esc(c.name)}" oninput="urSetCycle('name',this.value)"></label><label class="full">Description<textarea rows="3" maxlength="2000" oninput="urSetCycle('description',this.value)">${esc(c.description)}</textarea></label><label class="full">Review Type<select onchange="urSetCycle('type',this.value)">${['Standard Performance Review','360° Feedback','Probationary Review','Project-Based Review'].map(t=>`<option ${c.type===t?'selected':''}>${t}</option>`).join('')}</select></label>${[['Review Period Start Date','periodStart'],['Review Period End Date','periodEnd'],['Cycle Start Date','start'],['Submission Deadline','deadline']].map(([l,k])=>`<label>${l} <span class="required">*</span><input type="date" required value="${c[k]}" onchange="urSetCycle('${k}',this.value)"></label>`).join('')}</div>`:urStep===2?`<div class="toolbar urtoolbar"><label class="urfilter ursearch"><span>Search</span><input class="search" aria-label="Search cycle employees" value="${esc(urEmployeeSearch)}" placeholder="Search name or employee ID…" oninput="urEmployeeSearch=this.value;urDrawEmployeeLookup()"></label>${urSelect('Department','',['All departments',...new Set(data.employees.map(e=>e[3]))],urEmployeeDept,'urEmployeeDept=this.value;urDrawEmployeeLookup()')}<button onclick="urSelectAllEmployees()">Select All Filtered</button><button onclick="urWizard.participants=[];urSyncEvaluators();urDirty=true;render()">Clear selection</button><b id="urSelectedCount"></b></div><div class="tablewrap"><table><thead><tr><th>SELECT</th><th>EMPLOYEE</th><th>EMPLOYEE ID</th><th>DEPARTMENT</th><th>POSITION</th><th>IMMEDIATE SUPERVISOR</th></tr></thead><tbody id="urEmployeeLookup"></tbody></table></div>`:urStep===3?urEvaluatorStep():urStep===4?urTemplateStep():urLaunchSummary(c)}</div><div class="urerror" id="urWizardError" role="alert"></div><div class="urwizardfoot"><span>${c.participants.length} selected employees · ${c.evaluators.length} expected assignments</span><button onclick="urSaveCycleDraft()">Save as Draft</button>${urStep>1?`<button onclick="urWizardStep(${urStep-1})">Back</button>`:''}${urStep<5?`<button class="primary" onclick="urWizardStep(${urStep+1})">Continue →</button>`:`${c.start>urToday?`<button class="primary" onclick="urConfirmCycle('Scheduled')">Schedule Cycle</button>`:urCycleValidation(c).length===0&&c.deadline>=urToday?`<button class="primary" onclick="urConfirmCycle('Active')">Launch Cycle</button>`:'<span class="urmuted">Complete all required configuration to launch.</span>'}`}</div></section>`}
function urFilteredEmployees(){return data.employees.filter(e=>e.join(' ').toLowerCase().includes(urEmployeeSearch.toLowerCase())&&(urEmployeeDept==='All departments'||e[3]===urEmployeeDept))}
function urDrawEmployeeLookup(){$('#urEmployeeLookup').innerHTML=urFilteredEmployees().map(e=>`<tr><td><input type="checkbox" aria-label="Select ${esc(e[1])}" ${urWizard.participants.includes(e[0])?'checked':''} onchange="urToggleEmployee('${e[0]}',this.checked)"></td><td>${urDisplayPerson(e[0])}</td><td>${e[0]}</td><td>${esc(e[3])}</td><td>${esc(e[2])}</td><td>${esc(e[4])}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching employees.</td></tr>';$('#urSelectedCount').textContent=urWizard.participants.length+' selected'}
function urToggleEmployee(id,on){urWizard.participants=on?[...new Set([...urWizard.participants,id])]:urWizard.participants.filter(x=>x!==id);urSyncEvaluators();urDirty=true;urDrawEmployeeLookup()}
function urSelectAllEmployees(){urWizard.participants=[...new Set([...urWizard.participants,...urFilteredEmployees().map(e=>e[0])])];urSyncEvaluators();urDirty=true;render()}
function urSyncEvaluators(){const c=urWizard;c.evaluators=c.evaluators.filter(e=>c.participants.includes(e.subject)&&c.groups.includes(e.type));for(const subject of c.participants){if(c.groups.includes('Self')&&!c.evaluators.some(e=>e.subject===subject&&e.type==='Self'))c.evaluators.push({subject,reviewer:subject,type:'Self'});if(c.groups.includes('Manager')&&!c.evaluators.some(e=>e.subject===subject&&e.type==='Manager')){const reviewer=urSupervisor(subject);if(reviewer)c.evaluators.push({subject,reviewer,type:'Manager'})}}}
function urEvaluatorStep(){const c=urWizard;return `<div class="urevaluatorgroups">${urTypes.map(type=>`<label class="urcheck"><input type="checkbox" ${c.groups.includes(type)?'checked':''} onchange="urToggleGroup('${type}',this.checked)">${{Self:'Self-Assessment',Manager:'Manager Evaluation',Peer:'Peer Evaluation',Upward:'Upward / Direct Report Evaluation'}[type]}</label>`).join('')}</div><div class="notice">Immediate supervisors are suggested from employee records. Review the assignment, change a manager, and add multiple peer or upward evaluators. Duplicate evaluator + employee + type combinations are blocked.</div>${c.participants.map(subject=>`<section class="urassigncard"><div>${urDisplayPerson(subject)}<small>Immediate supervisor: ${esc(urPerson(subject).manager)}</small></div><div class="urassigngroups">${c.groups.map(type=>`<div><b>${type}</b><div class="urevaluatorchips">${c.evaluators.filter(e=>e.subject===subject&&e.type===type).map(e=>`<span class="urevaluatorchip">${esc(urPerson(e.reviewer).name)}${type!=='Self'?`<button aria-label="Remove ${esc(urPerson(e.reviewer).name)} ${type} assignment" onclick="urRemoveEvaluator('${subject}','${type}','${e.reviewer}')">×</button>`:''}</span>`).join('')||'<span class="required">No evaluator assigned</span>'}</div>${type!=='Self'?`<select aria-label="Add ${type} evaluator for ${esc(urPerson(subject).name)}" onchange="urAddEvaluator('${subject}','${type}',this.value);this.value=''" ${type==='Manager'&&c.evaluators.some(e=>e.subject===subject&&e.type===type)?'disabled':''}><option value="">${type==='Manager'?'Select manager…':'＋ Add evaluator…'}</option>${urPeople().filter(p=>p.id!==subject).map(p=>`<option value="${p.id}" ${c.evaluators.some(e=>e.subject===subject&&e.type===type&&e.reviewer===p.id)?'disabled':''}>${esc(p.name)} · ${esc(p.position)}</option>`).join('')}</select>`:''}</div>`).join('')}</div></section>`).join('')}<section class="urconfidentiality"><h2>Confidentiality & response threshold</h2><div class="formgrid"><label class="urcheck"><input type="checkbox" ${c.anonymousPeer?'checked':''} onchange="urSetCycle('anonymousPeer',this.checked)">Group peer feedback anonymously</label><label class="urcheck"><input type="checkbox" ${c.anonymousUpward?'checked':''} onchange="urSetCycle('anonymousUpward',this.checked)">Group upward feedback anonymously</label><label>Minimum responses per anonymous group<input type="number" min="2" max="10" step="1" value="${c.threshold}" onchange="urSetCycle('threshold',+this.value)"></label></div><p>Below this threshold, that group’s ratings and written feedback stay hidden—even after results are released. Evaluator identities are never shown in anonymous result groups.</p></section>`}
function urToggleGroup(type,on){urWizard.groups=on?[...new Set([...urWizard.groups,type])]:urWizard.groups.filter(t=>t!==type);urSyncEvaluators();urDirty=true;render()}
function urAddEvaluator(subject,type,reviewer){if(!reviewer)return;if(type==='Manager'&&urWizard.evaluators.some(e=>e.subject===subject&&e.type===type)||urWizard.evaluators.some(e=>e.subject===subject&&e.type===type&&e.reviewer===reviewer)){toast('This evaluator is already assigned');return}if(reviewer===subject){toast('Choose someone other than the employee');return}urWizard.evaluators.push({subject,type,reviewer});urDirty=true;render()}
function urRemoveEvaluator(subject,type,reviewer){urWizard.evaluators=urWizard.evaluators.filter(e=>!(e.subject===subject&&e.type===type&&e.reviewer===reviewer));urDirty=true;render()}
function urTemplateStep(){const c=urWizard,published=UR.templates.filter(t=>t.status==='Published');return `<div class="notice">Only published templates can be assigned. A form can be reused across evaluator groups and cycles. Each launched assignment stores its own template version.</div>${c.groups.map(type=>`<div class="urtemplatemapping"><div><h3>${{Self:'Self-Assessment',Manager:'Manager Evaluation',Peer:'Peer Evaluation',Upward:'Upward Evaluation'}[type]}</h3><small>${c.evaluators.filter(e=>e.type===type).length} evaluator assignments</small></div><select aria-label="${type} review template" onchange="urWizard.templates['${type}']=this.value;urDirty=true;render()"><option value="">Select a published template…</option>${published.map(t=>`<option value="${t.id}" ${c.templates[type]===t.id?'selected':''}>${esc(t.name)} · v${t.version}</option>`).join('')}</select>${c.templates[type]?`<button onclick="urPreviewTemplate('${c.templates[type]}')">Preview</button>`:''}</div>`).join('')}${!published.length?urEmpty('No published templates','Create and publish a form, then resume this setup.'):''}<button onclick="urCreateTemplateFromWizard()">＋ Create Template</button><small>Your current cycle setup will be preserved.</small>`}
function urCreateTemplateFromWizard(){UR.draftCycle={...urClone(urWizard),savedStep:urStep};urDirty=false;urPersist();urEditTemplate()}
function urLaunchSummary(c){const errors=urCycleValidation(c);return `<div class="ursummarygrid">${[['Cycle',c.name],['Review Type',c.type],['Review Period',date(c.periodStart)+' – '+date(c.periodEnd)],['Cycle Start',date(c.start)],['Submission Deadline',date(c.deadline)],['Employees',c.participants.length],['Expected Assignments',c.evaluators.length],['Anonymous Feedback',`Peer: ${c.anonymousPeer?'anonymous':'named'} · Upward: ${c.anonymousUpward?'anonymous':'named'} · Minimum ${c.threshold} responses`]].map(([l,v])=>`<div><small>${l}</small><b>${esc(v)}</b></div>`).join('')}</div><h2>Participants & assignments</h2><div class="tablewrap"><table><thead><tr><th>EMPLOYEE</th><th>EVALUATORS</th></tr></thead><tbody>${c.participants.map(id=>`<tr><td>${urDisplayPerson(id)}</td><td class="urwrap">${c.evaluators.filter(e=>e.subject===id).map(e=>`${e.type}: ${esc(urPerson(e.reviewer).name)}`).join('<br>')}</td></tr>`).join('')}</tbody></table></div><h2 style="margin:24px 0 12px">Selected templates</h2>${c.groups.map(type=>`<div class="urtemplatepair"><span>${type}</span><b>${esc(UR.templates.find(t=>t.id===c.templates[type])?.name||'Not selected')}</b></div>`).join('')}<div class="notice">${c.start>urToday?'Scheduled cycles generate assignments when their start date is reached in the sample workspace.':'Launching generates one review for every evaluator assignment.'} HR finalizes the workflow after all responses are submitted, then explicitly releases results.</div>${errors.length?`<div class="urerror">${errors.map(esc).join('<br>')}</div>`:''}`}
function urSaveCycleDraft(){if(!urHr())return;const c=urClone(urWizard);c.name=c.name.trim()||'Untitled review cycle';c.savedStep=urStep;c.status='Draft';const i=UR.cycles.findIndex(x=>x.id===c.id);if(i>=0)UR.cycles[i]=c;else UR.cycles.push(c);UR.draftCycle=c;urDirty=false;urAudit('Cycle draft saved: '+c.id);toast('Cycle draft saved');render()}
function urConfirmCycle(state){if(!urHr())return;const errors=urCycleValidation(urWizard);if(state==='Scheduled'&&urWizard.start<=urToday)errors.push('Use a future start date to schedule a cycle.');if(state==='Active'&&(urWizard.start>urToday||urWizard.deadline<urToday))errors.push('Immediate launch requires a current start date and a deadline that has not passed.');if(errors.length){$('#urWizardError').textContent=errors.join(' ');return}modal(state==='Active'?'Launch this review cycle?':'Schedule this review cycle?',state==='Active'?'Individual review assignments will be created now.':'Assignments will open on the scheduled start date.',`<div class="modalbody"><p>${esc(urWizard.name)} includes ${urWizard.participants.length} employees and ${urWizard.evaluators.length} evaluator assignments.</p></div>`,`<button onclick="closeModal()">Back to setup</button><button class="primary" onclick="urCommitCycle('${state}')">${state==='Active'?'Confirm Launch':'Confirm Schedule'}</button>`)}
function urGenerateAssignments(c){if(UR.assignments.some(a=>a.cycle===c.id))return;for(const e of c.evaluators){const t=(c.templateSnapshots||{})[e.type]||UR.templates.find(t=>t.id===c.templates[e.type]);UR.assignments.push({id:urUid('rev'),cycle:c.id,...urClone(e),deadline:c.deadline,template:urClone(t),state:'Not Started',answers:{},updated:urToday})}}
function urCommitCycle(state){if(!urHr()||urCycleValidation(urWizard).length)return;const c=urClone(urWizard);c.status=state;c.name=c.name.trim();c.templateSnapshots=Object.fromEntries(c.groups.map(type=>[type,urClone(UR.templates.find(t=>t.id===c.templates[type]))]));const i=UR.cycles.findIndex(x=>x.id===c.id);if(i>=0)UR.cycles[i]=c;else UR.cycles.push(c);if(state==='Active')urGenerateAssignments(c);UR.draftCycle=null;urDirty=false;urAudit('Cycle '+state.toLowerCase()+': '+c.id);closeModal();urDetail=c.id;urDetailTab='Overview';urScreen='cycle';urTab='Cycles';render();toast(state==='Active'?'Cycle launched; review assignments generated':'Cycle scheduled')}
function urOpenCycle(id){const c=urCycle(id);if(!c||!urHr()&&!c.participants.some(id=>id===urUser()||viewRole==='Manager'&&urTeam(id))&&!urCycleAssignments(c).some(a=>a.reviewer===urUser()))return;urGo(()=>{page='Reviews';urDetail=id;urDetailTab='Overview';urScreen='cycle';urTab='Cycles';render()})}
function urCycleDetail(){const c=urCycle(urDetail);if(!c)return urEmpty('Cycle not found','Return to Cycles to choose another record.');const all=urCycleAssignments(c).filter(urVisible),ids=c.participants.filter(id=>urHr()||id===urUser()||viewRole==='Manager'&&urTeam(id)),done=all.filter(a=>a.state==='Completed').length,submitted=all.filter(a=>a.state==='Submitted').length,ready=urCycleAssignments(c).length>0&&urCycleAssignments(c).every(a=>['Submitted','Completed'].includes(a.state));return urPageHead('Cycle Details',c.name,`<button onclick="urGoTab('Cycles')">← Back to Cycles</button>`)+`<div class="panel urcycledetailhead"><div><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><small>${esc(c.type)} · ${date(c.periodStart)} – ${date(c.periodEnd)}</small></div><div class="uractions">${urBadge(c.status)}${urHr()&&c.status==='Draft'?`<button onclick="urStartWizard('${c.id}')">Edit Cycle</button>`:''}${urHr()&&c.status==='Active'&&ready?`<button class="primary" onclick="urFinalizeCycle('${c.id}')">Finalize Cycle</button>`:''}${urHr()&&c.status==='Completed'&&!c.released?`<button class="primary" onclick="urReleaseCycle('${c.id}')">Release Results</button>`:''}${urHr()&&['Active','Scheduled','Draft'].includes(c.status)?`<button onclick="urCancelCycle('${c.id}')">Cancel Cycle</button>`:''}</div></div><div class="tabs urdetailtabs">${['Overview','Participants','Progress','Results'].map(t=>`<button class="${urDetailTab===t?'selected':''}" onclick="urDetailTab='${t}';render()">${t}</button>`).join('')}</div>${urDetailTab==='Overview'?urSummaryCards([['Employees',ids.length,'Participants in your scope'],['Review Assignments',all.length,'Visible individual assignments'],['Completion',all.length?Math.round(done/all.length*100)+'%':'0%','Completed workflows'],['Submitted',submitted,'Awaiting HR finalization']])+`<section class="panel urintro"><div class="ursummarygrid">${[['Cycle Start',date(c.start)],['Submission Deadline',date(c.deadline)],['Results',c.released?'Released to authorized users':'Not released'],['Anonymous Minimum',c.threshold+' responses per group']].map(([l,v])=>`<div><small>${l}</small><b>${esc(v)}</b></div>`).join('')}</div><div class="notice">${c.status==='Draft'?'No assignments are created until this cycle launches.':c.status==='Scheduled'?'Assignments will be generated when the sample workspace date reaches the cycle start.':c.status==='Active'?'Evaluators submit individual responses. HR can finalize the workflow once all assignments are submitted.':c.status==='Completed'?'The review workflow has been finalized. Results remain restricted until HR releases them.':'This cycle was cancelled. Its assignments are read only.'}</div></section>`:urDetailTab==='Participants'?`<section class="panel"><div class="tablewrap"><table><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>ASSIGNED EVALUATORS</th><th>COMPLETED</th><th>PENDING</th><th>STATUS</th></tr></thead><tbody>${ids.map(id=>{const as=all.filter(a=>a.subject===id),completed=as.filter(a=>a.state==='Completed').length,pending=as.filter(a=>!['Completed','Submitted'].includes(a.state)).length;return `<tr><td>${urDisplayPerson(id)}</td><td>${esc(urPerson(id).department)}</td><td class="urwrap">${c.evaluators.filter(e=>e.subject===id).map(e=>{const anon=e.type==='Peer'&&c.anonymousPeer||e.type==='Upward'&&c.anonymousUpward;return `${e.type}: ${anon?'Anonymous evaluator':esc(urPerson(e.reviewer).name)}`}).join('<br>')}</td><td>${completed} / ${as.length}</td><td>${pending}</td><td>${urBadge(completed===as.length&&as.length?'Completed':as.some(a=>a.state==='Submitted')?'Submitted':as.some(a=>a.state==='In Progress')?'In Progress':'Not Started')}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No evaluated employees in your scope. Your assigned questionnaire is available under Reviews.</td></tr>'}</tbody></table></div></section>`:urDetailTab==='Progress'?`<section class="panel urintro"><h2>Assignment completion</h2><div class="urwideprogress">${progress(all.length?Math.round(done/all.length*100):0)}<p>${done} completed / ${all.length} visible assignments · ${submitted} submitted</p></div>${urSummaryCards(['Not Started','In Progress','Submitted','Overdue'].map(s=>[s,all.filter(a=>urEffective(a)===s).length,'Individual assignments']))}<div class="tablewrap"><table><thead><tr><th>EMPLOYEE</th><th>TYPE</th><th>REVIEWER</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${all.map(a=>`<tr><td>${urDisplayPerson(a.subject)}</td><td>${a.type}</td><td>${urAnon(a)&&a.reviewer!==urUser()?'Anonymous evaluator':esc(urPerson(a.reviewer).name)}</td><td>${urBadge(urEffective(a))}</td><td>${urCanRead(a)?`<button class="textbtn" onclick="urOpenReview('${a.id}')">${urCanEdit(a)?'Open assigned review':'View response'}</button>`:'<span class="urmuted">Restricted response</span>'}${urHr()&&a.state==='Submitted'&&c.status==='Active'?`<button class="textbtn" onclick="urReopen('${a.id}')">Reopen</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No assignments generated yet.</td></tr>'}</tbody></table></div></section>`:urCycleResults(c,ids)}${urHr()&&c.status==='Active'&&!ready?'<div class="notice">Finalize Cycle becomes available after every assignment is Submitted. HR can reopen submitted responses from Progress before finalization.</div>':''}`}
function urFinalizeCycle(id){const c=urCycle(id),as=urCycleAssignments(c);if(!urHr()||c.status!=='Active'||!as.length||as.some(a=>!['Submitted','Completed'].includes(a.state)))return;modal('Finalize this cycle?','Every evaluator response has been received.',`<div class="modalbody"><p>All assignments will become Completed and locked. Results will remain hidden until you choose Release Results.</p></div>`,`<button onclick="closeModal()">Cancel</button><button class="primary" onclick="urDoFinalize('${id}')">Finalize Cycle</button>`)}
function urDoFinalize(id){const c=urCycle(id),as=urCycleAssignments(c);if(!urHr()||c.status!=='Active'||!as.length||as.some(a=>!['Submitted','Completed'].includes(a.state)))return;c.status='Completed';as.forEach(a=>a.state='Completed');urAudit('Cycle finalized: '+id);closeModal();render();toast('Cycle completed; results remain unreleased')}
function urReleaseCycle(id){const c=urCycle(id);if(!urHr()||c.status!=='Completed'||c.released)return;modal('Release review results?','Authorized employees and managers will be able to see results.',`<div class="modalbody"><p>Anonymous groups below ${c.threshold} responses will remain hidden. Individual evaluator identities will not appear in anonymous results.</p></div>`,`<button onclick="closeModal()">Cancel</button><button class="primary" onclick="urDoRelease('${id}')">Release Results</button>`)}
function urDoRelease(id){const c=urCycle(id);if(!urHr()||c.status!=='Completed')return;c.released=true;urAudit('Results released: '+id);closeModal();render();toast('Results released to authorized users')}
function urCancelCycle(id){const c=urCycle(id);if(!urHr()||!['Active','Scheduled','Draft'].includes(c.status))return;modal('Cancel this review cycle?','Existing responses are retained and become read only.',`<div class="modalbody"><p>This cycle will no longer accept submissions. Results will not be released.</p></div>`,`<button onclick="closeModal()">Keep cycle</button><button class="primary" onclick="urCycle('${id}').status='Cancelled';urCycle('${id}').released=false;urAudit('Cycle cancelled: ${id}');closeModal();render()">Cancel Cycle</button>`)}
function urResultGroups(c,id){return urTypes.map(type=>{const all=urCycleAssignments(c).filter(a=>a.subject===id&&a.type===type&&a.state==='Completed'),anonymous=type==='Peer'&&c.anonymousPeer||type==='Upward'&&c.anonymousUpward,hidden=anonymous&&c.groups.includes(type)&&all.length<c.threshold;return {type,all,anonymous,hidden,mean:hidden?null:urAvg(all.map(urMean))}})}
function urCycleResults(c,ids){if(!c.released)return `<section class="panel">${urEmpty('Results have not been released',urHr()?'Finalize all assignments, then choose Release Results. Confidential result summaries stay hidden until release.':'HR will release results once the review workflow is complete.')}</section>`;const allowed=ids.filter(id=>urCanResult(c,id)),means=allowed.map(id=>urAvg(urResultGroups(c,id).filter(g=>!g.hidden).flatMap(g=>g.all.map(urMean))));return urSummaryCards([['Released Results',allowed.length,'Employees visible to your role'],['Average Rating',urRating(urAvg(means)),'Mean of visible employee averages'],['Rating Scale','1–5','Never → Always'],['Confidentiality','Protected','Anonymous response thresholds applied']])+`<section class="panel"><div class="panelhead"><div><h2>Employee results</h2><p>Overall scores exclude Not Observed answers and withheld anonymous groups.</p></div>${allowed.length?`<button onclick="urExportResults('${c.id}')">↓ Export Results</button>`:''}</div><div class="tablewrap"><table><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>OVERALL RATING</th><th>COMPETENCY SUMMARY</th><th>ACTION</th></tr></thead><tbody>${allowed.map((id,i)=>`<tr><td>${urDisplayPerson(id)}</td><td>${esc(urPerson(id).department)}</td><td>${urRating(means[i])}</td><td class="urwrap">${urCompetencies(c,id).slice(0,2).map(([q,n])=>`${esc(q)} ${urRating(n)}`).join('<br>')||'No scored competencies'}</td><td><button class="textbtn" onclick="urOpenResult('${c.id}','${id}')">View Results ↗</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No employee results are available in your scope.</td></tr>'}</tbody></table></div></section>`}
function urCompetencies(c,id){const groups=urResultGroups(c,id).filter(g=>!g.hidden),map=new Map();for(const a of groups.flatMap(g=>g.all))for(const q of a.template.questions.filter(q=>q.type==='Rating')){const v=a.answers[q.id];if(v&&v!=='NO'){if(!map.has(q.title))map.set(q.title,[]);map.get(q.title).push(+v)}}return [...map].map(([k,v])=>[k,urAvg(v)])}
let urResultCycle=null,urResultSubject=null;
function urOpenResult(cycle,id){const c=urCycle(cycle);if(!c||!urCanResult(c,id))return;urGo(()=>{page='Reviews';urResultCycle=cycle;urResultSubject=id;urTab='Reviews';urScreen='result';render()})}
function urScoreBar(label,n){return `<div class="urscorebar"><span>${esc(label)}</span><div class="track"><i style="width:${n===null?0:n/5*100}%"></i></div><b>${urRating(n)}</b></div>`}
function urEmployeeResults(){const c=urCycle(urResultCycle),id=urResultSubject;if(!c||!urCanResult(c,id))return urEmpty('Results unavailable','Results have not been released to your role.');const groups=urResultGroups(c,id),visible=groups.filter(g=>!g.hidden).flatMap(g=>g.all),overall=urAvg(visible.map(urMean)),written=visible.flatMap(a=>a.template.questions.filter(q=>q.type!=='Rating'&&a.answers[q.id]).map(q=>({question:q.title,value:a.answers[q.id],type:a.type,anonymous:urAnon(a),reviewer:urPerson(a.reviewer).name}))),matching=word=>written.filter(w=>w.question.toLowerCase().includes(word));return urPageHead('Employee Review Summary',`${urPerson(id).name} · ${c.name}`,`<button onclick="urGoTab('Reviews')">← Back to Reviews</button>`)+`<div class="urdetailmeta panel">${urDisplayPerson(id)}<div><small>Cycle</small><b>${esc(c.name)}</b></div><div><small>Visibility</small><b>Results released</b></div><div><small>Overall Performance Rating</small><strong>${urRating(overall)}</strong></div></div><div class="notice">Scoring: average the observed rating answers within each response, then average the eligible response scores. Not Observed answers and anonymous groups below threshold are excluded. Narrative answers are never converted to scores.</div><div class="chartgrid"><section class="panel"><div class="panelhead"><div><h2>Competency Ratings</h2><p>Observed behaviors · 1 Never to 5 Always</p></div></div><div class="urresultbars">${urCompetencies(c,id).map(([q,n])=>urScoreBar(q,n)).join('')||'<p>No observed ratings were provided.</p>'}</div></section><section class="panel"><div class="panelhead"><div><h2>Self vs. Manager Rating</h2><p>Comparison of average observed ratings</p></div></div><div class="urresultbars">${['Self','Manager'].map(type=>urScoreBar(type,groups.find(g=>g.type===type).mean)).join('')}</div><div class="urresultbars"><h2>Aggregated 360° Feedback</h2>${groups.filter(g=>['Peer','Upward'].includes(g.type)).map(g=>g.hidden?`<div class="notice">${g.type} feedback withheld: fewer than ${c.threshold} completed responses. No score or written feedback is shown.</div>`:g.all.length?`<p>${g.type} · ${g.anonymous?'Anonymous grouped responses':'Named feedback'}</p>${urScoreBar(g.type,g.mean)}`:`<p class="urmuted">No ${g.type.toLowerCase()} feedback collected.</p>`).join('')}</div></section></div><div class="chartgrid">${[['Strengths',matching('strength')],['Areas for Improvement',matching('improv')]].map(([label,ws])=>`<section class="panel"><div class="panelhead"><h2>${label}</h2></div><div class="urwritten">${ws.map(w=>`<blockquote><small>${w.anonymous?'Anonymous '+w.type+' group':w.type+' perspective'}</small>${esc(w.value)}</blockquote>`).join('')||'<p>No written feedback in this category.</p>'}</div></section>`).join('')}</div><section class="panel"><div class="panelhead"><h2>Written Feedback</h2></div><div class="urwritten">${written.filter(w=>!w.question.toLowerCase().includes('strength')&&!w.question.toLowerCase().includes('improv')).map(w=>`<blockquote><small>${w.anonymous?'Anonymous '+w.type+' group':w.type+' perspective'} · ${esc(w.question)}</small>${esc(w.value)}</blockquote>`).join('')||'<p>No additional written feedback.</p>'}</div></section><section class="panel urfinalcomments"><h2>Manager’s Final Comments</h2>${viewRole==='Manager'&&urTeam(id)?`<label>Summary and next steps<textarea id="urFinalComment" rows="4" maxlength="3000">${esc(c.finalComments?.[id]||'')}</textarea></label><button class="primary" onclick="urSaveFinalComment('${c.id}','${id}')">Save final comments</button>`:`<p>${esc(c.finalComments?.[id]||'No final comments have been added by the manager.')}</p>`}</section>`}
function urSaveFinalComment(cycle,id){if(viewRole!=='Manager'||!urTeam(id))return;const c=urCycle(cycle);if(!c.released)return;c.finalComments??={};c.finalComments[id]=$('#urFinalComment').value.trim();urAudit('Manager final comments saved: '+cycle+' / '+id);toast('Final comments saved')}
function urExportResults(id){const c=urCycle(id);if(!c?.released)return;const ids=c.participants.filter(subject=>urCanResult(c,subject)),rows=[['Employee','Department','Cycle','Overall rating','Self','Manager','Peer','Upward'],...ids.map(subject=>{const gs=urResultGroups(c,subject);return [urPerson(subject).name,urPerson(subject).department,c.name,urRating(urAvg(gs.filter(g=>!g.hidden).flatMap(g=>g.all.map(urMean)))),...gs.map(g=>g.hidden?'Withheld':urRating(g.mean))]})];urDownloadCsv(rows,'released-review-results.csv')}
function urDownloadCsv(rows,name){const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
