roleHead=function(title,sub,action=''){if(!['Dashboard','Reports'].includes(title))return urOldRoleHead(title,sub,action);const cycles=UR.cycles.filter(c=>UR.assignments.some(a=>a.cycle===c.id&&urVisible(a)));if(!cycles.some(c=>c.id===urDashboardCycle))urDashboardCycle=cycles[0]?.id||'';return head(title,sub,action)+`<div class="scopebar"><span>${viewRole==='Employee'?'Personal workspace':viewRole==='Manager'?'Direct reports and assigned evaluations':'Organization-wide workspace'} · ${esc(roleName())}</span><label class="cyclepicker">REVIEW CYCLE<select aria-label="Dashboard review cycle" onchange="urDashboardCycle=this.value;render()">${cycles.map(c=>`<option value="${c.id}" ${urDashboardCycle===c.id?'selected':''}>${esc(c.name)} · ${c.status}</option>`).join('')}</select></label></div>`};
function urDashAssignments(){return UR.assignments.filter(a=>a.cycle===urDashboardCycle&&urVisible(a))}
roleStats=function(){const as=urDashAssignments(),gs=scopedGoals(),avg=gs.length?Math.round(gs.reduce((s,g)=>s+g.progress,0)/gs.length):0;return urSummaryCards([['Review Assignments',as.length,'Selected cycle · visible assignments'],['Completed Reviews',as.filter(a=>a.state==='Completed').length,'Finalized workflows'],['Submitted Responses',as.filter(a=>a.state==='Submitted').length,'Awaiting HR finalization'],['Goal Progress',avg+'%','Average across your visible goals']])};
charts=function(){const as=urDashAssignments(),done=as.filter(a=>a.state==='Completed').length,states=urStatus,cc=['#bccbd8','#73abda','#ab96d5','#6dbb9b','#e59a87'];let off=0;const circles=states.map((s,i)=>{const n=as.filter(a=>urEffective(a)===s).length,pct=as.length?n/as.length*100:0,svg=`<circle cx="70" cy="70" r="52" fill="none" stroke="${cc[i]}" stroke-width="15" pathLength="100" stroke-dasharray="${pct} ${100-pct}" stroke-dashoffset="${-off}"/>`;off+=pct;return svg}).join('');const donut=`<div class="donutwrap"><svg viewBox="0 0 140 140" role="img" aria-label="Review assignment statuses"><circle cx="70" cy="70" r="52" fill="none" stroke="#eef3f6" stroke-width="15"/><g transform="rotate(-90 70 70)">${circles}</g><text x="70" y="69" text-anchor="middle" font-size="24" fill="#334c61">${as.length?Math.round(done/as.length*100):0}%</text><text x="70" y="86" text-anchor="middle" font-size="9" fill="#8b9eac">COMPLETED</text></svg><div class="legend">${states.map((s,i)=>`<div><i style="background:${cc[i]}"></i><span>${s}</span><b>${as.filter(a=>urEffective(a)===s).length}</b></div>`).join('')}</div></div>`;const gs=scopedGoals(),es=scopedEmployees(),groups=viewRole==='Employee'?gs.map(g=>({name:g.name,n:g.progress})):[...new Set(es.map(e=>e[3]))].map(d=>{const names=es.filter(e=>e[3]===d).map(e=>e[1]),goals=gs.filter(g=>names.includes(g.employee));return {name:d,n:goals.length?Math.round(goals.reduce((s,g)=>s+g.progress,0)/goals.length):0}}),bars=`<div class="bars">${groups.map(g=>`<div class="barrow"><span title="${esc(g.name)}">${esc(g.name)}</span><div class="track"><i style="width:${g.n}%"></i></div><b>${g.n}%</b></div>`).join('')}<div class="axis"><span>0%</span><span>50%</span><span>100%</span></div></div>`;return `<div class="chartgrid">${chartPanel('Review Status','Individual assignments · selected cycle',donut)}${chartPanel(viewRole==='Employee'?'My Goal Progress':'Goal Progress by Department','Visible goals · independent of review cycles',bars)}</div><div class="chartgrid">${chartPanel('Evaluator Perspectives','Assignment counts by review type',`<div class="bars">${urTypes.map(type=>{const n=as.filter(a=>a.type===type).length;return `<div class="barrow"><span>${type}</span><div class="track"><i style="width:${as.length?n/as.length*100:0}%"></i></div><b>${n}</b></div>`}).join('')}</div>`)}${chartPanel('Next Actions','One workspace for forms, cycles, and responses',`<div class="actionlist"><div><span class="actionicon">▤</span><div><h3>${as.filter(a=>a.reviewer===urUser()&&urCanEdit(a)).length} assigned reviews to complete</h3><p>Save drafts and submit your questionnaire.</p></div><button class="textbtn" onclick="navigate('Reviews');urFilter.view='My Reviews';render()">Open →</button></div><div><span class="actionicon">◷</span><div><h3>${urHr()?'Manage review cycles':'Track review progress'}</h3><p>${urHr()?'Configure cycles, monitor submissions, and release results.':'View visible assignments and released results.'}</p></div><button class="textbtn" onclick="navigate('Reviews');urGoTab('Cycles')">View →</button></div><div class="notice">Submitted = response received. Completed = finalized workflow. Result release is a separate HR action.</div></div>`)}</div>`};
roleExport=function(){const rows=[['Employee','Cycle','Type','Reviewer','Due date','Status'],...urDashAssignments().map(a=>[urPerson(a.subject).name,urCycle(a.cycle).name,a.type,urAnon(a)&&a.reviewer!==urUser()?'Anonymous evaluator':urPerson(a.reviewer).name,a.deadline,urEffective(a)])];urDownloadCsv(rows,'review-assignment-progress.csv')};
const urRenderWithScroll=render;let urLastView='';render=function(){urRenderWithScroll();const key=page+'|'+urScreen+'|'+urTab+'|'+(urScreen==='wizard'?urStep:'');if(key!==urLastView){window.scrollTo(0,0);urLastView=key}};
